<section class="page-header"><div><a class="back-link" href="<?= url('invoices') ?>"><i class="fa-solid fa-arrow-left"></i> Back to invoices</a><h1>Create invoice</h1><p>Line totals, GST and outstanding balance are calculated on the server.</p></div></section>
<form method="post" action="<?= url('invoices') ?>" id="invoiceForm"><?= csrf_field() ?><div class="invoice-form-layout"><section class="panel form-panel"><div class="form-section"><h3>Invoice details</h3><div class="form-grid"><label>Client *<select name="client_id" id="invoiceClient" required><option value="">Select client</option><?php foreach($clients as $c):?><option value="<?= $c['id'] ?>"><?= e($c['company_name']) ?></option><?php endforeach;?></select></label><label>Project<select name="project_id" id="invoiceProject"><option value="">General billing</option><?php foreach($projects as $p):?><option value="<?= $p['id'] ?>" data-client="<?= $p['client_id'] ?>"><?= e($p['name']) ?></option><?php endforeach;?></select></label><label>Invoice type<select name="invoice_type"><option>Tax Invoice</option><option>Proforma Invoice</option><option>Credit Note</option></select></label><label>GST type<select name="gst_type"><option value="CGST_SGST">CGST + SGST</option><option value="IGST">IGST</option><option value="No Tax">No tax</option></select></label><label>Invoice date *<input type="date" name="invoice_date" value="<?= date('Y-m-d') ?>" required></label><label>Due date *<input type="date" name="due_date" value="<?= date('Y-m-d',strtotime('+30 days')) ?>" required></label></div></div><div class="form-section"><div class="section-title-row"><h3>Line items</h3><button class="button button-secondary button-sm" type="button" id="addInvoiceItem"><i class="fa-solid fa-plus"></i> Add line</button></div><div class="invoice-items" id="invoiceItems"><div class="invoice-item" data-row="0"><label class="item-description">Description *<input name="items[0][description]" required placeholder="Service or milestone"></label><label>HSN/SAC<input name="items[0][hsn_sac]" placeholder="998314"></label><label>Qty<input type="number" name="items[0][quantity]" value="1" min="0.01" step="0.01" required data-calc></label><label>Rate<input type="number" name="items[0][rate]" value="0" min="0" step="0.01" required data-calc></label><label>Tax %<input type="number" name="items[0][tax_percent]" value="18" min="0" max="100" step="0.01" data-calc></label><label>Discount<input type="number" name="items[0][discount]" value="0" min="0" step="0.01" data-calc></label><div class="item-total"><span>Line total</span><strong>₹0.00</strong></div><button class="icon-button danger remove-line" type="button" title="Remove"><i class="fa-solid fa-xmark"></i></button></div></div></div><div class="form-section"><div class="form-grid"><label>Additional charges<input type="number" name="additional_charges" value="0" min="0" step="0.01" data-summary></label><label class="wide">Notes<textarea name="notes" rows="3" placeholder="Notes visible on invoice"></textarea></label><label class="wide">Terms<textarea name="terms" rows="3">Payment due within 30 days. Please quote the invoice number with payment.</textarea></label></div></div></section><aside class="panel invoice-summary"><h3>Invoice summary</h3><dl><div><dt>Subtotal</dt><dd id="summarySubtotal">₹0.00</dd></div><div><dt>Tax</dt><dd id="summaryTax">₹0.00</dd></div><div><dt>Additional charges</dt><dd id="summaryAdditional">₹0.00</dd></div><div class="summary-total"><dt>Grand total</dt><dd id="summaryGrand">₹0.00</dd></div></dl><div class="inline-alert info"><i class="fa-solid fa-calculator"></i> Final values are recalculated securely on submission.</div><button class="button button-primary button-block"><i class="fa-solid fa-file-circle-plus"></i> Create draft invoice</button><a class="button button-secondary button-block" href="<?= url('invoices') ?>">Cancel</a></aside></div></form>
<script src="<?= asset('js/invoice.js') ?>?v=1.0.0" defer></script>
